import{z as i,x as n,o as r,c as l,q as e,j as t,D as E,d as s,s as B,S as o}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"虚拟化案例与收束","description":"","frontmatter":{"title":"虚拟化案例与收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/virt-case-map.md","filePath":"cs/virt-case-map.md","lastUpdated":1791063341000}'),c={name:"cs/virt-case-map.md"};function p(d,a,h,D,m,C){const A=n("Mermaid");return r(),l("div",null,[a[2]||(a[2]=e('<h1 id="虚拟化案例与收束" tabindex="-1">虚拟化案例与收束 <a class="header-anchor" href="#虚拟化案例与收束" aria-label="Permalink to &quot;虚拟化案例与收束&quot;">​</a></h1><div class="epigraph"><p>先问互信程度与密度目标，再问路径税单——机制是这三问的答案，不是立场。本课程的全部机制，最终都要落到某个具体负载的这三问上。</p><footer>—— 据 Firecracker、Kata Containers 与主流云平台公开架构资料整理</footer></div><p><a href="/cs/virt-performance-overhead">上一课</a>把开销按路径归账：计算、译址、每包、每笔、双份缓存。本课是「虚拟化与容器深入」的最后一课：先走五类真实负载，看机制如何被三问（互信、密度、路径）逼出来，再把整门课程收在一根轴上。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课给了税单，缺口是怎样在具体负载上用税单做决定。云上的实践已经把答案收敛成三问：租户之间互信到什么程度、密度目标是每请求一台机器还是每宿主一百个服务、负载的税单压在哪条路径上。这三问比任何「容器还是虚机」的立场之争都更有决定力；缺口是把它们钉成可执行的过滤器。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是用三问逐类过一遍真实负载——五类案例几乎覆盖了线上世界的全部形态。</p><p><strong>不可信多租户代码</strong>（函数计算、用户提交任务）：对手是租户自己，密度目标是每次调用一台「机器」。答案只能是微虚机：<a href="/cs/firecracker-microvm">Firecracker</a> 用砍光的设备模型把 VMM 信任面压小，冷启动压进百毫秒量级（据其公开数据），快照恢复把「每函数一内核」铺成常态——快照的状态倾倒与请求停顿错开，与数据库的<a href="/cs/fuzzy-checkpoint">模糊检查点</a>是同一哲学。<strong>互信的自家服务</strong>：对手不在租户间，密度与交付速度是主目标。容器加默认加固即可，防线在配置纪律（禁特权、裁 capabilities，见<a href="/cs/container-escape">容器逃逸</a>的合同），不必为不存在的对手付虚机税。<strong>AI 训练集群</strong>：卡比机器贵，环境一致性靠容器镜像，卡本身按上一课的光谱分——整卡直通或 MIG 切分，绝不在共享内核里裸奔。<strong>延迟敏感的网络面</strong>：负载均衡、网关，每包税是生死线，<a href="/cs/sriov-passthrough">SR-IOV</a> 或 <a href="/cs/dpdk-kernel-bypass">DPDK</a> 旁路买回吞吐，卖掉的是迁移与策略灵活性。<strong>遗留系统与运维弹性</strong>：OS 版本杂、要热迁移与超售，完整虚机加<a href="/cs/live-migration">热迁移</a>加<a href="/cs/memory-balloon">内存气球</a>仍是唯一全对的答案。</p>',8)),(r(),t(o,null,{default:E(()=>[B(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E8%B4%9F%E8%BD%BD%22%5D%20--%3E%20T%7B%22%E7%A7%9F%E6%88%B7%E4%BA%92%E4%BF%A1%E5%90%97%22%7D%0A%20%20T%20--%3E%7C%22%E4%B8%8D%E5%8F%AF%E4%BF%A1%22%7C%20MV%5B%22%E5%BE%AE%E8%99%9A%E6%9C%BA%3A%20Firecracker%20%E6%88%96%20Kata%22%5D%0A%20%20T%20--%3E%7C%22%E5%8F%AF%E4%BF%A1%22%7C%20D%7B%22%E5%AF%86%E5%BA%A6%E4%BC%98%E5%85%88%3F%22%7D%0A%20%20D%20--%3E%7C%22%E6%98%AF%22%7C%20CT%5B%22%E5%AE%B9%E5%99%A8%E5%8A%A0%E9%BB%98%E8%AE%A4%E5%8A%A0%E5%9B%BA%22%5D%0A%20%20D%20--%3E%7C%22%E5%90%A6%22%7C%20VM%5B%22%E8%99%9A%E6%9C%BA%E5%8A%A0%E7%83%AD%E8%BF%81%E7%A7%BB%22%5D%0A%20%20W%20--%3E%20P%7B%22%E8%B7%AF%E5%BE%84%E6%95%8F%E6%84%9F%3F%22%7D%0A%20%20P%20--%3E%7C%22%E6%AF%8F%E5%8C%85%22%7C%20BY%5B%22SR-IOV%20%E6%88%96%20DPDK%20%E6%97%81%E8%B7%AF%22%5D%0A%20%20P%20--%3E%7C%22%E6%95%B4%E5%8D%A1%22%7C%20GPU%5B%22%E7%9B%B4%E9%80%9A%E6%88%96%20MIG%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>五类案例摆开后，课程的骨架自己显形：所有机制躺在一根轴上。一端是<strong>共享内核</strong>——namespace 给视图，cgroup 给预算，隔离是查表与记账，无陷入、密度极高、信任面是整个内核；另一端是<strong>复制机器</strong>——陷入与模拟（第一课的谱系）、硬件辅助接住敏感指令、EPT 管两维译址、<a href="/cs/virtio">virtio</a> 定 I/O 契约，信任面缩到 VMM 但每个租户都要付整套机器的钱。隔离与开销沿这根轴<strong>同向移动</strong>：第二课挪接缝、第三课换后端、第五课砍软件路径、第六课选共享粒度，全是在轴上找点，从来不是逃离轴。没有免费的边界——安全课说信任面，开销课说路径税，说的是同一根轴的两端。</p><p><span class="marginnote">轴上还有一个常被漏掉的中间点：unikernel（本课程第一课的入口）把应用与库 OS 链成单映像交给 hypervisor——按租户裁内核，比微虚机更小，比容器更隔离；通用性差让它停在专用网关一类场景。收束时该记得：轴上的点不只有两个端点。</span></p><p><span class="marginnote">直觉类比：这根轴像住房光谱——共享内核是合租（每人都用同一栋楼的水电与大门，便宜、进门快，但门禁只有一把），完整虚机是独栋（每户自备全套管线，贵、慢，但墙是自己的）；微虚机是精装小公寓，MIG 切卡是同一套房里隔出的独立单间。选型不是站队，是按预算与室友可信度挑房。</span></p>',4)),(r(),t(o,null,{default:E(()=>[B(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20AXIS%5B%22%E9%9A%94%E7%A6%BB-%E5%BC%80%E9%94%80%E8%BD%B4%22%5D%20--%3E%20SK%5B%22%E5%85%B1%E4%BA%AB%E5%86%85%E6%A0%B8%3A%20namespace%20%2B%20cgroup%22%5D%0A%20%20SK%20--%3E%20SKTAX%5B%22%E5%87%A0%E4%B9%8E%E6%97%A0%E9%99%B7%E5%85%A5%E7%A8%8E%2C%20%E4%BF%A1%E4%BB%BB%E9%9D%A2%20%3D%20%E6%95%B4%E4%B8%AA%E5%86%85%E6%A0%B8%22%5D%0A%20%20AXIS%20--%3E%20MV%5B%22%E5%BE%AE%E8%99%9A%E6%9C%BA%3A%20%E8%A3%81%E5%89%AA%20VMM%22%5D%0A%20%20MV%20--%3E%20MVTAX%5B%22%E5%86%B7%E5%90%AF%E5%8A%A8%E7%99%BE%E6%AF%AB%E7%A7%92%2C%20%E4%BF%A1%E4%BB%BB%E9%9D%A2%E5%B0%8F%2C%20%E4%BB%98%E6%95%B4%E5%A5%97%E6%9C%BA%E5%99%A8%22%5D%0A%20%20AXIS%20--%3E%20FV%5B%22%E5%AE%8C%E6%95%B4%E8%99%9A%E6%9C%BA%3A%20QEMU%2FKVM%22%5D%0A%20%20FV%20--%3E%20FVTAX%5B%22EPT%20%E4%B8%8E%E5%8F%8C%E4%BB%BD%E7%BC%93%E5%AD%98%E7%A8%8E%2C%20%E6%8D%A2%E7%83%AD%E8%BF%81%E7%A7%BB%E4%B8%8E%E8%B6%85%E5%94%AE%22%5D%0A%20%20SKTAX%20--%3E%20SAME%5B%22%E9%9A%94%E7%A6%BB%E4%B8%8E%E5%BC%80%E9%94%80%E5%90%8C%E5%90%91%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20MVTAX%20--%3E%20SAME%0A%20%20FVTAX%20--%3E%20SAME%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<p><span class="marginnote">常见误区：初学者容易把「容器更安全」当成容器相对虚机的固有优点，或反过来以为「虚机一定更重所以该淘汰」——两种立场都错在把轴当成了站队。同一负载换三问的答案，同一种机制就会从「正确」变成「浪费」；判据是互信、密度、路径，不是机制名声。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课的案例是决策形态，不是产品评审：型号、版本与许可都在课程之外。三条悬而未决也一并交代——机密计算（TEE 虚机）改变了「宿主可信」这条前提，但租户互打仍要本课的轴来分析；WASM 一类语言级沙箱试图在轴外另立一档，隔离语义还在收敛；嵌套与跨宿主 GPU 迁移仍是边缘能力。这些不改变收束的判据：<strong>互信、密度、路径三问不变时，答案就在轴上</strong>。五栏主干给了机制的原件，本课程给了机制的账本；再往深的每一项技术，都该能用这三问定位。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>决策三问：租户互信程度、密度目标、负载路径；机制是三问的答案。</li><li>五案例各得其所：不可信进微虚机，互信走加固容器，训练按卡分，延迟面旁路，遗留上虚机。</li><li>全课程一根轴：共享内核（视图加预算）到复制机器（陷入加模拟），隔离与开销同向移动。</li><li>没有免费的边界；unikernel、机密计算、语言沙箱都是轴上或轴边的中间点。</li><li>出处：据 Firecracker、Kata Containers、KVM/QEMU 与云平台公开架构资料整理。</li></ul>',5))])}const T=i(c,[["render",p]]);export{F as __pageData,T as default};
